questions.solution:
#include <stdio.h>

int main() {
    // Declare and initialize variables
    char initial = 'R';
    int age = 19;
    float percentage = 87.5;

    // Print the variables
    printf("Student Initial : %c\n", initial);
    printf("Age             : %d years\n", age);
    printf("Percentage      : %.2f%%\n", percentage);

    return 0;
}

